<?php
declare(strict_types=1);require __DIR__.'/workflow-core.php';if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$today=new DateTimeImmutable('today',new DateTimeZone('Asia/Riyadh'));$sent=0;$errors=0;
foreach(trackingRecords() as $id=>$raw){try{trackingLocked(function()use($id,$today,&$sent){$record=workflowProject(trackingRead($id));if(!$record['reminders_enabled'])return;foreach($record['invoices'] as &$invoice){if(in_array($invoice['status'],['Paid','Void'],true))continue;$due=DateTimeImmutable::createFromFormat('!Y-m-d',$invoice['due_date'],new DateTimeZone('Asia/Riyadh'));if(!$due)continue;$days=(int)$today->diff($due)->format('%r%a');$key=match($days){3=>'before-3',0=>'due',-7=>'after-7',default=>''};if($days<0&&$invoice['status']==='Sent'){$invoice['status']='Overdue';workflowActivity($record,'payment_status_changed',$invoice['number'].' → Overdue');}if($key===''||in_array($key,$invoice['reminders']??[],true))continue;$token=workflowOpenToken($record);$amount=workflowFormat($invoice['amount_due_cents'],$record['currency']);$plain="Hello {$record['client_name']},\n\nReminder: invoice {$invoice['number']} for $amount is due {$invoice['due_date']}.\n\nPayment details:\n{$record['payment_details']}\n\nTracking link: ".workflowCustomerUrl($token);aorSendMail($record['client_email'],$record['client_name'],'Payment reminder: '.$invoice['number'],aorMailTemplate('Payment reminder','<p>'.nl2br(htmlspecialchars($plain)).'</p>'),$plain);$invoice['reminders'][]=$key;$sent++;workflowActivity($record,'email_sent','Payment reminder '.$key.' for '.$invoice['number']);}unset($invoice);$record['updated_at']=gmdate('c');$record['revision']=bin2hex(random_bytes(16));trackingWrite($id,$record);});}catch(Throwable $e){$errors++;error_log('AOR reminder: '.$id.' '.$e->getMessage());}}
echo "Payment reminders sent: $sent; project errors: $errors\n";
